# 🟢 低风险：只读/信息收集，通常无副作用
#!/bin/bash
# etcd 成员管理脚本

ENDPOINTS="https://127.0.0.1:2379"
CA="/etc/kubernetes/pki/etcd/ca.crt"
CERT="/etc/kubernetes/pki/etcd/server.crt"
KEY="/etc/kubernetes/pki/etcd/server.key"

# 1. 查看 etcd 集群状态
show_status() {
    echo "=== etcd Cluster Status ==="
    ETCDCTL_API=3 etcdctl endpoint status --cluster \
        --endpoints=$ENDPOINTS \
        --cacert=$CA --cert=$CERT --key=$KEY \
        --write-out=table
}

# 2. 查看 etcd 成员列表
show_members() {
    echo "=== etcd Members ==="
    ETCDCTL_API=3 etcdctl member list \
        --endpoints=$ENDPOINTS \
        --cacert=$CA --cert=$CERT --key=$KEY \
        --write-out=table
}

# 3. 添加新成员 (External etcd 模式)
add_member() {
    local peer_url=$1
    echo "Adding member with peer URL: $peer_url"
    ETCDCTL_API=3 etcdctl member add new-etcd-node \
        --peer-urls=$peer_url \
        --endpoints=$ENDPOINTS \
        --cacert=$CA --cert=$CERT --key=$KEY
}

# 4. 移除成员
remove_member() {
    local member_id=$1
    echo "Removing member: $member_id"
    ETCDCTL_API=3 etcdctl member remove $member_id \
        --endpoints=$ENDPOINTS \
        --cacert=$CA --cert=$CERT --key=$KEY
}

# 5. 检查集群健康
check_health() {
    echo "=== etcd Health ==="
    ETCDCTL_API=3 etcdctl endpoint health --cluster \
        --cacert=$CA --cert=$CERT --key=$KEY
}

# 执行
case "$1" in
    status) show_status ;;
    members) show_members ;;
    add) add_member "$2" ;;
    remove) remove_member "$2" ;;
    health) check_health ;;
    *) echo "Usage: $0 {status|members|add <peer_url>|remove <member_id>|health}" ;;
esac

# keepalived.conf (主节点)
vrrp_instance VI_1 {
    state MASTER
    interface eth0
    virtual_router_id 51
    priority 101
    advert_int 1
    authentication {
        auth_type PASS
        auth_pass K8sHaProxy123
    }
    virtual_ipaddress {
        192.168.1.100/24
    }
}

# keepalived.conf (备节点)
vrrp_instance VI_1 {
    state BACKUP
    interface eth0
    virtual_router_id 51
    priority 100
    advert_int 1
    authentication {
        auth_type PASS
        auth_pass K8sHaProxy123
    }
    virtual_ipaddress {
        192.168.1.100/24
    }
}

stream {
    upstream kubernetes {
        server 192.168.1.10:6443 max_fails=3 fail_timeout=30s;
        server 192.168.1.11:6443 max_fails=3 fail_timeout=30s;
        server 192.168.1.12:6443 max_fails=3 fail_timeout=30s;
    }

    server {
        listen 6443;
        proxy_pass kubernetes;
        proxy_timeout 30s;
        proxy_connect_timeout 5s;
    }
}
